/* 拾史桌面端交互原型。仅本地示例；不连接任何模型或支付服务。 */
const app=document.getElementById('app');
const pageNames={home:'我的作品',preferences:'创作偏好',input:'输入材料',story:'确认故事',production:'自动制作',storyboard:'分镜与素材',review:'审阅成片',export:'导出作品'};
let selectedShot=0;let savedPrefs={audience:'对历史文化感兴趣的普通观众',duration:'60–90 秒',visual:'器物纪录风',tone:'有悬念、说人话、克制不夸张',voice:'清晰自然、平稳讲述',budget:'',review:true};
try{const stored=localStorage.getItem('shishi-prototype-prefs');if(stored)savedPrefs={...savedPrefs,...JSON.parse(stored)}}catch(e){}
const art=(cls='')=>`<svg class="art-svg ${cls}" viewBox="0 0 300 340" xmlns="http://www.w3.org/2000/svg" aria-label="抽象器物视觉示意 不代表真实文物"><defs><linearGradient id="bronze" x1="0" x2="1"><stop stop-color="#143c36"/><stop offset=".25" stop-color="#5c8067"/><stop offset=".46" stop-color="#a2aa77"/><stop offset=".69" stop-color="#4a7a65"/><stop offset="1" stop-color="#153e36"/></linearGradient><linearGradient id="neck" x1="0" x2="1"><stop stop-color="#274b3e"/><stop offset=".4" stop-color="#9ca273"/><stop offset="1" stop-color="#234e43"/></linearGradient><radialGradient id="shine"><stop stop-color="#c0c799" stop-opacity=".6"/><stop offset="1" stop-color="#43694e" stop-opacity="0"/></radialGradient></defs><ellipse cx="155" cy="308" rx="76" ry="13" fill="#0c1e19" opacity=".25"/><path d="M116 59 Q150 45 184 59 L181 72 Q168 73 171 98 C171 119 191 127 208 144 C233 168 238 215 216 250 L199 274 L196 300 Q151 313 108 300 L106 274 C83 254 69 229 74 195 Q77 159 102 140 C121 124 130 112 129 98 L127 73 L115 72Z" fill="url(#bronze)" stroke="#a1b083" stroke-opacity=".4"/><ellipse cx="150" cy="59" rx="34" ry="8" fill="#719078"/><ellipse cx="150" cy="58" rx="27" ry="4" fill="#294b3d"/><path d="M128 76 L172 76 M129 86 L171 86 M109 143 Q154 153 201 143 M80 177 Q151 197 223 177 M78 208 Q151 232 224 208 M104 272 Q151 289 200 272 M109 290 Q150 304 195 290" fill="none" stroke="#b3bc8c" stroke-opacity=".55" stroke-width="3"/><path d="M91 174 L106 155 L122 180 L139 160 L156 186 L173 163 L192 181 L207 158 L218 175 M86 207 L108 192 L127 215 L147 197 L167 220 L188 197 L213 210" fill="none" stroke="#294e41" stroke-opacity=".85" stroke-width="5"/><ellipse cx="130" cy="188" rx="61" ry="99" fill="url(#shine)"/><path d="M112 141 C125 121 135 102 133 81" stroke="#d0cfa0" stroke-opacity=".3" fill="none" stroke-width="3"/><g fill="#c1c79a" opacity=".28"><circle cx="95" cy="192" r="3"/><circle cx="169" cy="238" r="5"/><circle cx="193" cy="157" r="3"/><circle cx="116" cy="257" r="3"/><circle cx="183" cy="113" r="2"/></g></svg>`;
const pill=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
const button=(s,route,cls='')=>`<button type="button" class="${cls}" data-route="${route}">${s}</button>`;
const header=(eye,title,sub,actions='')=>`<div class="page-title"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="title-actions">${actions}</div></div>`;
const steps=(n)=>`<div class="steps">${['输入材料','确认故事','自动制作','审阅成片'].map((s,i)=>`${i?'<span class="connector"></span>':''}<span class="step ${i===n?'active':''}"><i>${i<n?'✓':i+1}</i>${s}</span>`).join('')}</div>`;
function shell(route,body){return `<div class="desktop-notice">电脑端原型 · 建议使用 1280px 及以上宽度查看</div><div class="shell"><aside class="sidebar"><a href="#home" class="brand"><span class="mark">拾</span><div><strong>拾史</strong><span>STORIES FROM CULTURE</span></div></a><div class="nav-label">创作空间</div><a href="#home" class="side-link ${route==='home'?'active':''}"><i>▦</i>我的作品</a><a href="#input" class="side-link ${route==='input'?'active':''}"><i>＋</i>新建作品</a><a href="#preferences" class="side-link ${route==='preferences'?'active':''}"><i>☷</i>创作偏好</a><div class="side-divider"></div><div class="nav-label">当前项目</div><a href="#story" class="side-project">◦ 器物里的细节</a><a href="#production" class="side-project">◦ 查看制作进度</a><a href="#storyboard" class="side-project">◦ 分镜与素材</a><div class="side-note"><div class="line" style="background:#41604b"></div><span class="avatar">我</span>　个人创作空间<br><br>让资料成为故事<br>让故事形成作品</div></aside><div class="workspace"><div class="topbar"><div class="breadcrumb">创作空间　/　<b>${pageNames[route]}</b></div><div class="topright"><span class="demo-badge">交互原型 · 示例数据</span><span>默认由 GPT 编排</span><span class="avatar">我</span></div></div><main class="page">${body}<div class="bottom-note"><span>SHISHI / DESKTOP v1.0</span><span>本原型不上传资料、不生成媒体、不产生费用</span></div></main></div></div>`}
function home(){return header('YOUR CREATIVE SPACE','把书页里的线索，变成值得看的故事','从一段材料出发。偏好只设一次，制作交给工作台。',button('＋ 新建作品','input','primary'))+`<div class="hero"><div><div class="eyebrow">YOUR FIRST STORY STARTS HERE</div><h2>你决定讲什么，其余交给创作流程。</h2><p>上传资料，确认故事，最后看成片。分镜和提示词无需逐项操作。</p>${button('开始一条新故事　→','input','primary small')}</div><div class="hero-art" aria-hidden="true"><div class="hero-tile">原始材料<div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></div><div class="hero-tile" style="position:relative">${art()}<span style="position:relative">故事画面</span></div><div class="hero-tile">完整作品<div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></div></div></div><div class="section-heading"><h2>最近的作品 <span class="muted">／ 演示项目</span></h2><span class="muted">所有作品　⌄</span></div><div class="three-col"><article class="panel project-card"><div class="cover"><div class="cover-title">器物里的<br>细节<small>LOOK CLOSER · EPISODE 01</small></div>${art()}</div><div class="project-body">${pill('待确认故事')}<h3>一处细节，怎么看懂一件器物</h3><div class="muted">旁白知识短片 · 60–90 秒 · 竖屏</div><div class="project-meta"><span class="muted">演示项目 · 非真实任务</span>${button('继续创作 →','story','small')}</div></div></article><article class="panel project-card"><div class="cover sand"><div class="cover-title" style="color:#7a7757">先观察<br>再提问<small style="color:#8a9278">A DIFFERENT WAY TO SEE</small></div>${art('crop')}</div><div class="project-body">${pill('制作进度示意','amber')}<h3>从器物的轮廓开始观察</h3><div class="muted">旁白知识短片 · 竖屏 · 示例</div><div class="project-meta"><span class="muted">演示项目 · 非真实任务</span>${button('查看进度 →','production','small')}</div></div></article><div class="empty-add"><div><div class="plus">＋</div><h3 style="font-weight:500">下一条故事，等你开启</h3><p class="muted">一本书、一件器物、一个好问题。</p>${button('上传第一份材料','input','quiet small')}</div></div></div><div class="preset-bar" style="margin-top:23px"><span>✓ 已载入默认偏好：普通文化观众 · 旁白知识短片 · 器物纪录风</span><a href="#preferences">调整创作偏好 →</a></div>`}
function preferences(){return header('CREATION PREFERENCES','定义你的创作习惯','设置一次，后续作品自动继承。本条的临时调整不会覆盖长期偏好。',pill('默认模板'))+`<div class="two-col"><div class="panel"><h2>内容与表达</h2><div class="form-grid"><label class="field">面向谁讲述<select name="audience"><option>对历史文化感兴趣的普通观众</option><option>亲子家庭与青少年</option><option>文博深度爱好者</option></select></label><label class="field">单条长度<select name="duration"><option>60–90 秒</option><option>30–60 秒</option><option>90–180 秒</option></select></label><label class="field">内容形式<input value="旁白知识短片" readonly></label><label class="field">讲述语气<select name="tone"><option>有悬念、说人话、克制不夸张</option><option>轻松有趣、生活化类比</option><option>温暖细腻、故事感强</option></select></label><div class="field full">画面风格<div class="choice-grid" id="visual-choices"><button class="choice selected" data-visual="器物纪录风"><div class="choice-visual">${art()}</div><strong>器物纪录风</strong><span>实物参考 · 细节特写</span></button><button class="choice" data-visual="国风绘本"><div class="choice-visual">${art()}</div><strong>国风绘本</strong><span>统一插画 · 温和叙事</span></button><button class="choice" data-visual="电影故事感"><div class="choice-visual">${art()}</div><strong>电影故事感</strong><span>场景氛围 · 克制运动</span></button></div></div><label class="field">旁白声音<select name="voice"><option>清晰自然、平稳讲述</option><option>温暖亲切、娓娓道来</option><option>有活力、节奏明快</option></select></label><label class="field">单片费用上限<input name="budget" type="number" min="0" step="1" placeholder="尚未设置（元）"><span class="muted">未设置时，不提交付费生成。</span></label></div><div class="line"></div><h3>什么时候需要我确认</h3><label class="checkrow"><input name="review" type="checkbox" checked>制作前确认故事方案；分镜、图片与剪辑自动推进</label><div class="muted">关键事实存疑、超预算或连续失败时，才暂停请你处理。</div><details class="show-details"><summary>其他默认设置与模型记录</summary><p>9:16 竖屏 · 简体中文字幕 · 轻配乐 · 原图优先<br>GPT 负责编排与文字，图片工具按任务能力路由；具体模型以接入验证为准。</p></details><div class="footer-actions"><span class="save-notice">新作品使用保存后的偏好版本</span><button class="primary" data-action="save-prefs">保存默认偏好　→</button></div></div><aside><div class="side-preview"><div class="preview-title">器物里的<br>细节<small>STORIES IN THE DETAILS</small></div>${art('big')}<div class="preview-bottom">先看见一个细节<br>再讲清一个问题。</div><span class="art-note">抽象视觉示意</span></div><div class="preference-summary"><span class="label">当前风格预览</span><br>克制的光影，清晰的观察线索。<br>原图与生成画面各有来源标记。<div class="line"></div>偏好决定表达方式。<br>事实依据始终来自可核对的资料。</div></aside></div>`}
function input(){return header('NEW STORY','这次，想讲一个什么故事？','给出材料即可。没有明确想法时，GPT 会结合资料提出故事方案。',button('返回作品','home','quiet'))+steps(0)+`<div class="two-col"><div><div class="panel"><h2>01　导入你的材料</h2><div class="upload-zone"><div class="upload-icon">↥</div><h3>把书页照片或 PDF 拖到这里</h3><p>也可以粘贴正文。正式版支持 JPG、PNG 与 PDF。</p><button class="small" data-action="choose-files">选择本地材料</button><input class="file-drop" id="files" type="file" multiple accept="image/jpeg,image/png,application/pdf"></div><div class="inline" style="justify-content:space-between"><span class="label">演示材料列表</span>${pill('仅用于展示页面','gray')}</div><div id="file-list">${[12,13,14].map(n=>`<div class="file-row"><div class="file-thumb"></div><div><strong style="font-weight:400">书页示例_${n}.jpg</strong><div class="file-meta">示意文件 · 尚未导入真实资料</div></div><span class="push muted">P${n}　⋮</span></div>`).join('')}</div><details class="show-details"><summary>直接粘贴文字或补充书目信息</summary><label class="field"><textarea placeholder="粘贴正文；可附书名、作者、版本及页码"></textarea></label></details></div><div class="panel" style="margin-top:20px"><h2>02　本次想法 <span class="muted">／ 可留空</span></h2><label class="field"><textarea id="brief" placeholder="例如：从器物的一个细节切入，讲给第一次接触这个主题的人听。"></textarea></label><div class="footer-actions"><span class="muted">系统先整理资料，遇到关键疑点再提醒。</span>${button('生成故事方案　→','story','primary')}</div></div></div><aside><div class="panel"><h2>本次创作设定</h2>${pill('继承默认偏好')}<div class="line"></div><div class="label">受众</div><p style="font-size:12px">${esc(savedPrefs.audience)}</p><div class="label">形式与长度</div><p style="font-size:12px">旁白知识短片 · ${esc(savedPrefs.duration)}</p><div class="label">视觉与声音</div><p style="font-size:12px">${esc(savedPrefs.visual)}<br>${esc(savedPrefs.voice)}</p><div class="line"></div><div class="inline"><span class="muted">9:16 竖屏</span><span class="muted">简体中文字幕</span></div><details class="show-details"><summary>仅本条调整</summary><label class="field">目标长度<select><option>继承默认</option><option>30–60 秒</option><option>60–90 秒</option></select></label><p>正式版保存为本条覆盖，不修改默认值。</p></details></div><div class="note-block">✓ 来源和页码随作品保存<br>✓ 不让不确定的识别结果变成确定结论<br>✓ 实物照片与生成素材分别标记</div></aside></div>`}
const narration=[['00–08','开场 · 先抛出问题','第一次看见一件器物，你会先看什么？是颜色、纹样，还是它整体的形状？'],['08–25','展开 · 让观察变得具体','先别急着寻找答案。把视线放慢一点：看看口沿怎样收起，轮廓怎样转折，再看看纹样停在哪里。'],['25–48','证据 · 把判断交还给资料','这些细节值得提问，但观察并不等于结论。回到书页，找到对应的描述，再区分哪些是可见事实，哪些是作者的解释。'],['48–结束','收束 · 留下一个观察方法','下一次走进展厅，不妨多停留一会儿。从一个细节开始，也许你会提出一个更好的问题。']];
function story(){return header('STORY PROPOSAL','先确认，这是不是你想讲的故事','只判断故事方向和表达。分镜、提示词与后续制作会自动继续。',button('回到材料','input','quiet'))+steps(1)+`<div class="script-layout"><article class="panel script-page"><div class="script-header"><div class="inline">${pill('故事方案 v1')}<span class="muted">示例旁白 · 不含真实文物史实</span><button class="small quiet push" data-action="edit-script">编辑旁白</button></div><h2>一处细节，<br>怎么看懂一件器物？</h2><div class="muted">观察切入　／　提问推进　／　回到资料</div></div><div id="script-text">${narration.map(n=>`<section class="script-section"><div class="script-time">${n[0]}<br>时长示意</div><div class="script-copy"><label>${n[1]}</label><p>${n[2]} <sup data-action="source" style="cursor:pointer">来源</sup></p></div></section>`).join('')}</div><div class="inline"><span class="muted">最终时长以配音为准；真实作品需绑定来源。</span><button class="small quiet push" data-action="listen">试听旁白示意</button></div></article><aside><div class="panel"><h2>这一条要讲清什么</h2><p style="font-size:13px;line-height:1.9;color:#6e8060">用一个观察方法，帮助观众从“看过一件器物”，走向“看见一处细节”。</p><div class="line"></div><div class="label">表达设定</div><div class="note-card">普通文化观众<br>有悬念、克制、不夸张<br>器物纪录风 · 原图优先</div><div class="line"></div><div class="inline"><h3 style="margin:0">资料依据</h3><button class="small quiet push" data-action="source">查看</button></div><div class="source-chip">▤　原书页与事实引用<br>　　<span class="muted">待真实材料导入</span></div><div class="muted">示例展示讲述结构，不代替原书内容。</div></div><div class="panel" style="margin-top:18px"><h3>想换一种讲法？</h3><label class="field"><textarea id="story-feedback" placeholder="例如：开头更有悬念；语气轻松一点。" style="min-height:80px"></textarea></label><button class="small" data-action="revise-story" style="margin-top:12px">按意见调整</button></div></aside></div><div class="approval-bar"><div><strong style="font-weight:500;font-size:13px">故事确认后，后续步骤自动推进</strong><div class="muted">费用未设置时停在付费任务前；当前仅演示页面流转。</div></div>${button('认可故事，开始制作　→','production','primary')}</div>`}
function production(){const tasks=[['✓','整理材料与事实','提取来源，保留疑点记录','已完成'],['✓','剧本、分镜与旁白','依据确认版本拆分镜头','已完成'],['✓','分镜图片','统一风格与器物参考','已完成'],['◌','镜头视频与静态画面','仅必要镜头使用视频生成','进行中'],['5','合成剪辑与字幕','依据实际配音校准镜头时长','等待中']];return header('AUTOMATIC PRODUCTION','故事正在成为画面','你可以离开页面。正式版会保存任务状态，回来后继续查看。',button('查看分镜与素材','storyboard','quiet'))+steps(2)+`<div class="two-col"><div class="panel progress-panel"><div class="progress-title"><div><h2>器物里的细节</h2><span class="muted">后台工作流 · 示例进度</span></div>${pill('制作中 · 示意')}</div><div class="progress-track"><div class="progress-fill"></div></div>${tasks.map((t,i)=>`<div class="task-line ${i===3?'running':''}"><div class="round">${t[0]}</div><div>${t[1]}<div class="desc">${t[2]}</div></div><div class="state">${t[3]}</div></div>`).join('')}<div class="footer-actions"><button class="quiet small" data-action="pause">暂停后续任务示意</button><span class="muted">没有需要你逐项确认的镜头。</span></div><details class="show-details"><summary>展开执行记录</summary><p>正式版记录输入版本、模型、服务商任务 ID 和状态。超时先查询既有任务，不自动重复提交付费任务。</p></details></div><aside><div class="panel"><div class="inline"><h2 style="margin:0">最近产物</h2><a href="#storyboard" class="push muted">查看全部 →</a></div><div class="preview-mini-grid">${[0,1,2,3].map(i=>`<div class="mini-art ${i%2?'light':''}">${art(i===2?'crop':'')}<b>S0${i+1}</b></div>`).join('')}</div><p class="muted">抽象器物视觉示意，非文物复原图。</p></div><div class="panel" style="margin-top:18px"><h3>生成费用边界</h3><div class="label">单片上限</div><p style="font-size:20px;margin:6px 0">${savedPrefs.budget?esc(savedPrefs.budget)+' 元':'尚未设置'}</p><p class="muted">示例进度不代表任务已提交或费用已发生。</p><button class="small" data-action="budget">查看预算暂停状态</button></div><button class="primary" data-route="review" style="width:100%;margin-top:18px">预览制作完成后的页面　→</button></aside></div>`}
const shotNames=['问题开场','轮廓观察','局部特写','回到书页','细节对照','收束与留白'];
function storyboard(){return header('STORYBOARD & ASSETS','分镜与素材','默认由系统整理；需要精修时，再进入这里查看和替换。',button('返回制作进度','production','quiet'))+`<div class="preset-bar"><span>器物里的细节　／　示例镜头表　／　镜头数量由故事结构决定</span><span>非必经操作页</span></div><div class="tabs"><button class="active" data-asset-tab="images">分镜图片</button><button data-asset-tab="clips">镜头片段</button><button data-asset-tab="prompts">提示词与参考</button></div><div class="storyboard-grid">${shotNames.map((s,i)=>`<article class="panel shot-card"><div class="shot-art ${i%3===1?'light':i%3===2?'gray':''}">${art(i===2?'crop':'')}<span class="image-indicator">视觉示意</span><span class="art-note">非真实文物形制</span></div><div class="shot-body"><div class="shot-meta"><span>S0${i+1}</span><span>时长待配音校准</span></div><h3>${s}</h3><p class="asset-description">${['器物局部显现，引出提问','静态构图，突出整体轮廓','近距离观察，不增添形制','真实项目使用原文或证据图','对照细节与资料描述','留白，给观众一个观察问题'][i]}</p><div class="inline" style="margin-top:14px">${pill('示例素材','gray')}<button class="small quiet push" data-action="shot" data-shot="${i}">详情与替换 →</button></div></div></article>`).join('')}</div><div class="approval-bar"><span class="muted">不修改也可直接审阅成片。这里的操作只在需要时使用。</span>${button('去审阅成片　→','review','primary')}</div>`}
function review(){return header('REVIEW YOUR FILM','看一遍，然后告诉我怎么改','一句话提出修改；系统定位受影响的旁白、镜头、字幕和声音。',button('查看分镜','storyboard','quiet'))+steps(3)+`<div class="player-layout"><div><div class="player-shell"><div class="player-stage"><div class="video-frame"><div class="video-top">器物里的细节<small>LOOK CLOSER · EPISODE 01</small></div>${art()}<div class="play-circle" data-action="play" style="cursor:pointer">▷</div><div class="video-caption">从一个细节开始，提出更好的问题。</div><span class="art-note">成片布局示意 · 无真实视频</span></div></div><div class="player-controls"><button data-action="play" aria-label="播放预览示意">▷</button><span>时间待实际渲染</span><div class="player-scrub"></div><span>9:16　HD</span></div></div><div class="timeline"><div class="inline" style="justify-content:space-between"><span class="label">制作时间线 · 只在需要时展开精修</span><span class="muted">条块为布局示意</span></div><div class="track"><span class="track-label">画面</span>${[1,2,3,4,5,6].map(i=>`<span class="segment">S0${i}</span>`).join('')}</div><div class="track"><span class="track-label">旁白</span><span class="segment audio">完整旁白音轨 · 以实际时码对齐</span></div><div class="track"><span class="track-label">字幕</span><span class="segment subtitles">简体中文字幕</span></div></div></div><aside class="panel feedback-panel"><h2>希望哪里更好一点？</h2><p class="muted">说感受，也可以指定具体镜头。</p><textarea id="film-feedback" placeholder="例如：开头节奏快一点，第二个镜头换成原图，音乐再小一点。"></textarea><div class="feedback-choice"><button data-suggestion="开头节奏快一点">节奏更快</button><button data-suggestion="音乐再小一点">音乐更轻</button><button data-suggestion="字幕再大一点">字幕更清楚</button></div><button class="primary" style="width:100%" data-action="film-feedback">按意见修改</button><div class="line"></div><h3>修改记录</h3><div id="feedback-list"><div class="feedback-item">当前为首版成片布局<small>待真实任务完成后显示修改记录</small>${pill('示例 v1','gray')}</div></div><div class="line"></div><div class="muted">调整字幕和音量不会重生成画面。涉及新增付费任务时，先检查剩余预算。</div><button class="quiet small" data-action="source" style="margin-top:13px">查看来源与说明</button></aside></div><div class="approval-bar"><div><strong style="font-weight:500;font-size:13px">这条故事，可以交付了</strong><div class="muted">导出成片、字幕、封面和来源清单。</div></div>${button('认可成片，准备导出　→','export','primary')}</div>`}
function exportPage(){return header('EXPORT & REUSE','把这一条，变成下一条的起点','作品、来源与项目记录一起保留。下一次继续使用你的默认偏好。',button('返回审阅','review','quiet'))+`<div class="export-hero"><div class="success-circle">✓</div><div><h2>交付包已就绪 <span class="muted">／ 页面状态示意</span></h2><p>器物里的细节　·　旁白知识短片　·　竖屏</p></div><button class="primary push" data-action="download">下载交付包　↓</button></div><div class="two-col"><div class="panel"><div class="inline"><h2 style="margin:0">作品文件</h2><span class="push export-note">示例清单，不含真实成片</span></div><table class="export-list"><thead><tr><th>文件</th><th>格式</th><th>用途</th></tr></thead><tbody>${[['成片','MP4','发布与交付'],['字幕','SRT','校对与后续修改'],['封面','PNG','发布封面'],['发布文案','TXT','标题与简介'],['来源清单','JSON / MD','书页、引用与素材来源'],['项目记录','JSON','偏好、版本和镜头关联']].map((f,i)=>`<tr><td><span class="fileicon">${['VID','TXT','IMG','TXT','REF','PRJ'][i]}</span>${f[0]}</td><td>${f[1]}</td><td>${f[2]}</td></tr>`).join('')}</tbody></table><div class="footer-actions"><span class="muted">不包含 API 密钥、临时链接与其他私密配置。</span><button class="small" data-action="download">查看导出说明</button></div></div><aside><div class="panel"><h2>发布文案</h2><span class="label">标题示例</span><p style="font-size:15px">一处细节，怎么看懂一件器物？</p><div class="line"></div><span class="label">简介示例</span><p style="font-size:12px;color:#81916f;line-height:1.9">从轮廓与纹样开始观察，再回到资料寻找依据。下次走进展厅，试着多停留一会儿。</p><button class="small quiet" data-action="copy">复制文案</button></div><div class="subtle-box">保留这次创作方法<br><span class="muted">长期偏好仍沿用原版本。单条修改不会自动覆盖默认设置。</span></div><button class="primary" data-route="input" style="width:100%;margin-top:18px">用默认偏好，开始下一条　→</button></aside></div>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(text){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),6000)}
function modal(type){document.querySelector('.modal-backdrop')?.remove();const d=document.createElement('div');d.className='modal-backdrop';let body='';if(type==='budget')body=`${pill('需要处理','amber')}<h2>费用边界还没确定，先停在这里</h2><p>故事与已有产物会保留。设置可执行的单片预算并取得实际报价后，才能继续提交付费任务。</p><div class="modal-row"><span>本批次</span><span>待生成镜头 · 数量由实际任务决定</span></div><div class="modal-row"><span>服务商报价</span><span>尚未取得</span></div><div class="modal-row"><span>单片上限</span><span>${savedPrefs.budget?esc(savedPrefs.budget)+' 元':'尚未设置'}</span></div><div class="modal-row"><span>自动付费重试</span><span>关闭</span></div><div class="actions"><button data-action="close-modal">保留并稍后处理</button><button class="primary" data-route="preferences">去设置费用上限</button></div>`;else if(type==='source')body=`${pill('来源与疑点')}<h2>让每个结论找得到依据</h2><p>这里展示书页、识读文本与故事句子的对应关系。没有真实材料时，不生成虚构页码和史实。</p><div class="source-page"><h4>书页原文区域</h4>原页照片与正文在这里并排定位。<br><mark>与当前句子关联的文字会高亮。</mark><br>器名、年代或关键解释存在冲突时，先补证或改写。</div><div class="modal-row"><span>当前示例</span><span>未导入真实书页</span></div><div class="actions"><button data-action="close-modal">知道了</button><button class="primary" data-route="input">回到材料</button></div>`;else body=`${pill('S0'+(selectedShot+1)+' · 可选精修')}<h2>${shotNames[selectedShot]}</h2><div class="shot-art" style="height:220px;border-radius:8px">${art()}<span class="art-note">视觉示意，不代表真实文物</span></div><p>正式版在此显示旁白、参考来源、图片提示词和运动要求。替换素材后只标记受影响部分。</p><div class="actions"><button data-action="close-modal">保留当前</button><button class="primary" data-action="replace">替换素材示意</button></div>`;d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${type==='budget'?'预算暂停':type==='source'?'来源与疑点':'镜头详情'}"><button class="modal-close" data-action="close-modal" aria-label="关闭">×</button>${body}</section>`;document.body.append(d);d.querySelector('button')?.focus()}
function render(){document.querySelector('.modal-backdrop')?.remove();document.querySelector('.toast')?.remove();const route=location.hash.slice(1).split('?')[0]||'home';const screens={home,preferences,input,story,production,storyboard,review,export:exportPage};app.innerHTML=shell(screens[route]?route:'home',(screens[route]||home)());if(route==='preferences'){Object.keys(savedPrefs).forEach(k=>{const e=document.querySelector(`[name="${k}"]`);if(e){if(e.type==='checkbox')e.checked=savedPrefs[k];else e.value=savedPrefs[k]}});document.querySelectorAll('[data-visual]').forEach(b=>b.classList.toggle('selected',b.dataset.visual===savedPrefs.visual))}window.scrollTo(0,0)}
window.addEventListener('hashchange',render);
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-action],a');if(!t)return;if(t.dataset.route){location.hash=t.dataset.route;document.querySelector('.modal-backdrop')?.remove()}if(t.dataset.visual){savedPrefs.visual=t.dataset.visual;document.querySelectorAll('[data-visual]').forEach(b=>b.classList.toggle('selected',b===t));toast('已选择 '+t.dataset.visual+'，保存后作为默认。')}if(t.dataset.suggestion)document.getElementById('film-feedback').value=t.dataset.suggestion;if(t.dataset.assetTab){document.querySelectorAll('[data-asset-tab]').forEach(b=>b.classList.toggle('active',b===t));document.querySelectorAll('.asset-description').forEach((el,i)=>el.textContent=t.dataset.assetTab==='prompts'?'提示词示意：以确认参考为依据，保持形制与统一光影。':t.dataset.assetTab==='clips'?'视频任务与片段在真实制作后显示；支持静态画面替代。':['器物局部显现，引出提问','静态构图，突出整体轮廓','近距离观察，不增添形制','真实项目使用原文或证据图','对照细节与资料描述','留白，给观众一个观察问题'][i])}
switch(t.dataset.action){case'save-prefs':{const b=document.querySelector('[name=budget]');if(!b.checkValidity()){b.reportValidity();break}['audience','duration','tone','voice','budget','review'].forEach(k=>{const el=document.querySelector(`[name="${k}"]`);savedPrefs[k]=el.type==='checkbox'?el.checked:el.value});try{localStorage.setItem('shishi-prototype-prefs',JSON.stringify(savedPrefs))}catch(e){}toast('已在本地保存原型偏好。没有提交模型任务或付费授权。');break}case'budget':modal('budget');break;case'source':modal('source');break;case'shot':selectedShot=Number(t.dataset.shot)||0;modal('shot');break;case'close-modal':document.querySelector('.modal-backdrop')?.remove();break;case'replace':toast('正式版可上传替代素材，绑定当前镜头并重新检查依赖。');break;case'choose-files':document.getElementById('files').click();break;case'pause':toast('示意：暂停尚未提交的任务；已提交任务需查询服务商状态，费用可能已发生。');break;case'edit-script':{const p=document.getElementById('script-text');p.contentEditable=p.contentEditable!=='true';t.textContent=p.contentEditable==='true'?'完成编辑':'编辑旁白';if(p.contentEditable==='true')p.focus();toast('原型中可编辑旁白；正式版将保存新版本并分析影响。');break}case'listen':case'play':toast('当前是原型，没有真实音频或视频；不会播放或调用模型。');break;case'revise-story':toast('示意：根据意见生成新剧本版本，保留当前方案供比较。');break;case'film-feedback':{const v=document.getElementById('film-feedback').value.trim();if(!v){toast('先写一句修改意见。');break}document.getElementById('feedback-list').innerHTML=`<div class="feedback-item">${esc(v)}<small>意见已记入页面示意；尚未执行生成或剪辑</small>${pill('待处理 · 示意','amber')}</div>`;toast('正式版先分析受影响部分；需要新费用时检查预算。');break}case'download':toast('原型没有真实成片可下载；页面展示正式版的交付包内容。');break;case'copy':toast('文案复制交互示意：正式版复制当前项目的标题与简介。');break}});
document.addEventListener('change',e=>{if(e.target.id==='files'){const list=document.getElementById('file-list');list.replaceChildren();Array.from(e.target.files).forEach(f=>{const row=document.createElement('div');row.className='file-row';const name=document.createElement('span');name.textContent=f.name;const note=document.createElement('span');note.className='push muted';note.textContent='仅显示本地名称 · 未上传';row.append(name,note);list.append(row)});toast('原型仅显示文件名，不上传、识读或保存文件内容。')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.modal-backdrop')?.remove()});
render();
